ON CONFLICT(path) DO UPDATE SET
  title = CASE WHEN seo_pages.title IS NULL OR seo_pages.title = '' THEN EXCLUDED.title ELSE seo_pages.title END,
  description = CASE WHEN seo_pages.description IS NULL OR seo_pages.description = '' THEN EXCLUDED.description ELSE seo_pages.description END,
  keywords = CASE WHEN seo_pages.keywords IS NULL OR seo_pages.keywords = '' THEN EXCLUDED.keywords ELSE seo_pages.keywords END,
  og_title = CASE WHEN seo_pages.og_title IS NULL OR seo_pages.og_title = '' THEN EXCLUDED.og_title ELSE seo_pages.og_title END,
  og_description = CASE WHEN seo_pages.og_description IS NULL OR seo_pages.og_description = '' THEN EXCLUDED.og_description ELSE seo_pages.og_description END,
  updated_at = now();
